using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BNTunnelReview {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_DetailMezzanine/";static string O=>R+"/Docs/Review/2026-11-10_B2_DomeNetwork/";static Vector3 origin=new Vector3(0,-34,0);
 static Scene Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");return s;}
 static JObject Plan()=>JObject.Parse(File.ReadAllText(H+"layout.json"));static List<Vector3> Points(JToken t)=>t["path"].Select(v=>origin+new Vector3((float)v[0],0,-(float)v[1])).ToList();
 static Vector3 At(List<Vector3> ps,float d){for(int i=1;i<ps.Count;i++){float l=Vector3.Distance(ps[i-1],ps[i]);if(d<=l)return Vector3.Lerp(ps[i-1],ps[i],Mathf.Max(0,d/l));d-=l;}return ps.Last();}
 static Vector3 Pos(List<Vector3> ps,float d,float side,float y){var p=At(ps,d);var dir=(At(ps,d+.02f)-At(ps,d-.02f)).normalized;return p+Vector3.Cross(Vector3.up,dir)*side+Vector3.up*y;}
 static bool ca,cb;static float Y(float d,float len)=>2.42f*Mathf.Clamp01(Mathf.Min(ca?1:(d-1.6f)/3.9f,cb?1:(len-1.6f-d)/3.9f));
 public static object Routes(){var s=Check();var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var pos=player.transform.position;bool enabled=cc.enabled;float hh=cc.height;float testedRadius=cc.radius;var center=cc.center;var rows=new List<object>();int lowerSamples=0,upperSamples=0,blockedStand=0;try{cc.enabled=false;Physics.SyncTransforms();foreach(var t in Plan()["tunnels"]){string id=(string)t["id"];float len=(float)t["length"];var ps=Points(t);var newer=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B2_DomeNetwork/layout.json"))["tunnels"].FirstOrDefault(v=>(string)v["id"]==id);ca=newer!=null&&(bool)newer["connectedA"];cb=newer!=null&&(bool)newer["connectedB"];var errors=new List<object>();int blocked=0,upper=0;
 for(float d=.4f;d<len-.4f;d+=.25f){var p=Pos(ps,d,1.30f,0);var hits=Physics.OverlapCapsule(p+Vector3.up*.39f,p+Vector3.up*1.47f,.30f,~0,QueryTriggerInteraction.Ignore).Where(c=>c!=cc).ToArray();bool floor=Physics.Raycast(p+Vector3.up*.16f,Vector3.down,out var hit,.35f,~0,QueryTriggerInteraction.Ignore);lowerSamples++;if(hits.Length>0||!floor){if(errors.Count<12)errors.Add(new{route="lower",d,floor,hits=hits.Select(c=>c.name).ToArray()});}}
 for(float d=5.6f;d<len-5.6f;d+=.25f){var p=Pos(ps,d,0,2.42f);var hits=Physics.OverlapCapsule(p+Vector3.up*.35f,p+Vector3.up*.92f,.29f,~0,QueryTriggerInteraction.Ignore).Where(c=>c!=cc).ToArray();bool floor=Physics.Raycast(p+Vector3.up*.15f,Vector3.down,out var hit,.30f,~0,QueryTriggerInteraction.Ignore);var stand=Physics.OverlapCapsule(p+Vector3.up*.35f,p+Vector3.up*1.50f,.29f,~0,QueryTriggerInteraction.Ignore).Where(c=>c!=cc).ToArray();upper++;upperSamples++;if(stand.Length>0){blocked++;blockedStand++;}if(hits.Length>0||!floor||stand.Length==0){if(errors.Count<12)errors.Add(new{route="upper",d,floor,standingBlocked=stand.Length>0,hits=hits.Select(c=>c.name).ToArray()});}}
 var movements=new List<object>();foreach(bool reverse in new[]{false,true})foreach(bool crouch in new[]{false,true}){cc.enabled=false;cc.height=crouch?1.2f:hh;cc.center=center-Vector3.up*(hh-cc.height)*.5f;float start=reverse?len-.5f:.5f;var startP=Pos(ps,start,crouch?0:1.3f,crouch?Y(start,len):0);player.transform.position=startP+Vector3.up*(cc.height*.5f-cc.center.y+.025f);cc.enabled=true;Physics.SyncTransforms();float maxMiss=0;int steps=0;bool pass=true;int nn=Mathf.CeilToInt((len-1)/.18f);for(int i=1;i<=nn;i++){float d=reverse?len-.5f-(len-1)*i/nn:.5f+(len-1)*i/nn;var target=Pos(ps,d,crouch?0:1.3f,crouch?Y(d,len):0);float miss=0;for(int k=0;k<24;k++){var delta=target-player.transform.position;delta.y=0;miss=delta.magnitude;if(miss<.025f)break;cc.Move(delta.normalized*Mathf.Min(.065f,miss)+Vector3.down*.025f);steps++;}for(int settle=0;settle<10;settle++){var f=cc.Move(Vector3.down*.035f);if((f&CollisionFlags.Below)!=0)break;}float feet=player.transform.position.y+cc.center.y-cc.height*.5f;maxMiss=Mathf.Max(maxMiss,miss);if(miss>.12f||Mathf.Abs(feet-target.y)>.23f){pass=false;movements.Add(new{reverse,crouch,passed=false,d,miss,feet,expected=target.y,steps});break;}}if(pass)movements.Add(new{reverse,crouch,passed=true,maxMiss,steps});cc.enabled=false;}
 rows.Add(new{id,passed=errors.Count==0&&movements.All(x=>(bool)x.GetType().GetProperty("passed").GetValue(x)),upperSamples=upper,standingBlocked=blocked,errors,movements});}
 }finally{cc.enabled=false;cc.height=hh;cc.center=center;player.transform.position=pos;cc.enabled=enabled;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}var result=new{controllerHeight=hh,controllerRadius=testedRadius,lowerSamples,upperSamples,standingBlocked=blockedStand,routes=rows};File.WriteAllText(O+"all_tunnels.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{lowerSamples,upperSamples,standingBlocked=blockedStand,routes=rows};}
 static void Shot(string name,Vector3 pos,Vector3 target,float fov=78){var g=new GameObject("BD_TemporaryCamera");g.hideFlags=HideFlags.HideAndDontSave;var c=g.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.nearClipPlane=.035f;c.farClipPlane=240;c.fieldOfView=fov;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1440,900,24){antiAliasing=4};var old=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1440,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1440,900),0,0);tex.Apply();File.WriteAllBytes(O+name+".png",tex.EncodeToPNG());}finally{RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
 public static object Capture(){var s=Check();var p=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool on=p.activeSelf;p.SetActive(false);try{foreach(string id in new[]{"T01","T14"}){var t=Plan()["tunnels"].Single(v=>(string)v["id"]==id);var ps=Points(t);Shot(id+"_lower",Pos(ps,2,1.30f,1.65f),Pos(ps,9,.3f,2));Shot(id+"_upper",Pos(ps,7,0,3.43f),Pos(ps,14,0,3.40f));Shot(id+"_entry",Pos(ps,.3f,-.7f,1.65f),Pos(ps,7,0,2.0f));}var plan=JObject.Parse(File.ReadAllText(R+"/SourceAssets/B2_FullFloor/plan.json"));foreach(string id in new[]{"E01","E02","N01","C02"}){var r=plan["rooms"].Single(v=>(string)v["id"]==id);float rad=(float)r["r"];var center=origin+new Vector3((float)r["x"],0,-(float)r["v"]);Shot("room_"+id,center+new Vector3(-rad*.35f,1.65f,-rad*.60f),center+new Vector3(0,1.6f,rad*.2f));}}finally{p.SetActive(on);EditorSceneManager.OpenScene(s.path);}return new{images=10};}
 public static object Show(){var s=Check();var t=Plan()["tunnels"].First();var ps=Points(t);var g=new GameObject("BD_View");g.transform.position=Pos(ps,8,0,3.42f);g.transform.LookAt(Pos(ps,14,0,3.15f));var view=SceneView.lastActiveSceneView??EditorWindow.GetWindow<SceneView>();view.orthographic=false;view.sceneLighting=true;view.drawGizmos=false;view.AlignViewToObject(g.transform);view.Focus();UnityEngine.Object.DestroyImmediate(g);Selection.activeGameObject=null;SceneView.RepaintAll();return "T01 upper maintenance pipes and crouching walkway";}
}
